from collections import defaultdict

MOD = 1000000007

def parse_input() -> dict[str, str]:
    s1, s2, s3 = input().strip(), input().strip(), input().strip()
    return {'s1': s1, 's2': s2, 's3': s3}

def pairwise_equal_substrings(s1: str, s2: str, s3: str) -> int:
    memo = defaultdict(int)

    def dfs(i, visited):
        if i == len(s3):
            return visited

        result = 0
        for j in range(i, len(s3)):
            substring = s1[i:j+1] if visited & 1 else s2[j-i+1]

            if substring not in memo:
                memo[substring] = dfs(j + 1, visited | 1)

            result = (result + memo[substring]) % MOD

        return result % MOD

    return sum(dfs(0, 0), dfs(0, 0)) % MOD

def solution(input_data: dict[str, str]):
    return [pairwise_equal_substrings(**input_data)] * len(input_data), "\n".join(map(str, pairwise_equal_substrings(**input_data)))

