def max_total_path_length(H, roads):
    aliases = defaultdict(list)
    for pair in roads:
        A, B = pair
        aliases[A].append(B)
        aliases[B].append(A)

    def solve(start):
        queue = [(0, start)]
        visited = set()
        path = []

        while queue:
            count, curr = queue.pop(0)
            if curr == start:
                return len(path) * 2
            if curr in path:
                continue
            if curr in visited:
                subnet = 1
                i = len(path) - 1
                while i > 0 and path[i] in visited:
                    i -= 1
                subnet = len(visited) - i - 1
            else:
                subnet = 0
            visited.add(curr)
            path.append(curr)

            for next_ in aliases[curr]:
                if next_ not in visited:
                    queue.append((1 + count, next_))

