class SegmentTree:
    def __init__(self, arr, mod):
        n = len(arr)
        self.size = 2*n - 1
        self.tree = [0] * (2 * self.size - 1)
        self.mod = mod

        self.build(0, n - 1, arr)

    def build(self, left, right, arr):
        if left == right:
            self.tree[self.size - 1 - left] = arr[left]
        else:
            mid = (left + right) // 2
            self.build(left, mid, arr)
            self.build(mid + 1, right, arr)
            self.tree[self.size - 1 - left] = (self.tree[self.size - 2 - left] * (self.tree[self.size - 1 - (left + 1)] * 1000000007 + 1) % self.mod + self.tree[self.size - 1 - (left + 1)]) % self.mod

    def range_sum(self, i, j):
        result = 0
        while i <= j:
            if i % 2 == 1:
                result = (result + (self.tree[i] * 1000000007 + 1) % self.mod) % self.mod
            if j % 2 == 0:
                result = (result + self.tree[j] % self.mod) % self.mod
            i = (i + 1) // 2
            j = (j - 1) // 2
        return result

    def update(self, i, v):
        while i <= self.size - 1:
            self.tree[i] = (self.tree[i] * v % self.mod + 1) % self.mod
            i = (i + 1) // 2

