from collections import defaultdict

def swap(strs, i, j):
    for k in range(i, j + 1):
        strs[k] = strs[k][::-1]

def bfs(tree, root):
    n = len(tree)
    d = defaultdict(int)
    visited = [False] * n 
    q = []
    d[root] = 1
    q.append(root)

    while q:
        cur = q.pop(0)

        for i in range(len(tree[cur])):
            next_node = tree[cur][i]
            if not visited[next_node]:
                visited[next_node] = True
                d[next_node] = d[cur] + 1
                q.append(next_node)

    return max(d.values())

def solve(n, q, s):
    t = defaultdict(list)
    tree = list(s)
    for i in range(len(s) // 2):
        u, v = ord(s[i * 2]) - ord('['), ord(s[i * 2 + 1]) - ord('(')
        t[u].append(v)
        t[v].append(u)

    for i in range(len(t)):
        adj = []
        for to in t[i]:
            if to >= i + 1:
                for prev in t[to]:
                    # Using a function to swap characters
                    swap(adj, i, prev)
        adj.append(i)
        t[i] = adj

    tree = t[n].copy()
    tree += range(n + 1, max(t) + 2)
    tree += range(max(t) + 2)

    return bfs(tree, 0)

