import sys

def dijkstra(graph, start):
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        cost, node = heapq.heappop(pq)
        if cost > dist[node]:
            continue
        for neighbor, weight in graph[node]:
            if dist[neighbor] > cost + weight:
                dist[neighbor] = cost + weight
                heapq.heappush(pq, (dist[neighbor], neighbor))
    return dist

def answer_queries(graph, queries):
    for u, v in queries:
        shortest_path = dijkstra(graph, u) + dijkstra(graph, v) - dijkstra(graph, u + v)
        shortest_path[u + v] = shortest_path[(u, v)] = min(shortest_path[u + v], shortest_path[(u, v)])
        for node in shortest_path:
            shortest_path[node] = min(shortest_path[node], shortest_path[node - 1] + 1)
        print(shortest_path[v])

