from math import gcd

def max_gcd(A, M, n):
    def dp(X, i, carry, prv, psum):
        if i == n:
            return (carry == 0 and psum == 0)
        if (X == 0):
            return 0
        gap = min(n - i, X) + 1
        res = 0
        for j in range(gap):
            new_psum = psum + X - j
            new_carry = (X - j) * gcd(A[i], X - j) + carry
            new_prv = j + prv
            if X - j > 0:
                res = max(res, dp(X - j, i + 1, new_carry, new_prv, new_psum))
        return res

    return dp(M, 0, 0, 0, 0)

