def gcd_sum(A, M):
    if M == 0:
        return -1

    n = len(A)
    total_sum = sum(A)

    if total_sum < M:
        return 0

    max_gcd = 0
    for i in range(n):
        for j in range(i, n):
            diff_sum = sum(A[k] - A[j] for k in range(n) if k != j)
            if diff_sum == M:
                gcd = max(math.gcd(A[i] - A[j], diff_sum) * (math.gcd(A[i] - A[j], M) == 1) + i + j, max_gcd)
            elif diff_sum > M:
                break
            else:
                gcd = max(math.gcd(A[i] - A[j], diff_sum) * (math.gcd(A[i] - A[j], M) == 1) + i + j, max_gcd)
                break
        else:
            continue
        break

