def find_max_total_length(edges):
    n = len(edges) + 1
    max_km = 0
    node = {}

    for edge in edges:
        a, b = edge
        if a not in node:
            node[a] = 0
            node[b] = float('inf')
        else:
            node[a] += 1
        if b not in node:
            node[b] = 0
            node[a] = float('-inf')
        else:
            node[b] -= 1

    pq = []
    for node_id in node:
        if node[node_id] > 0:
            heapq.heappush(pq, [node[node_id], node_id])

    while pq:
        node, friend = heappop(pq)
        while node + friend > max_km:
            max_node = friend + node
            if max_km < max_node:
                max_km = max_node
            if friend not in node or friend == nex[friend]:
                break
            node[friend] = node[friend + 1]
            node[friend + 1] = nex[friend]
            if node[friend] > 0:
                heappush(pq, [node[friend], friend])
            nex[friend], nex[nex[friend]] = nex[friend], friend
            nex[friend] += -friend  # change nex in order to avoid vector stl to disturb befores

    for friend in edges:
        if node.get(friend) != friend + 1:
            nex[friend], nex[nex[friend]] = nex[nex[friend]], friend
            nex[friend] += -friend

    return max_km

