            time += map[i][j] * scaygerboss_time
            target = (i, j)
            dist = 9999999999
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if (ni, nj) in scaygers_set:
                    next_time = time + 1
                    continue

                if (ni, nj) in obstacles_set:
