def query(node, start, end, l, r, prefix_sum):
    if r < start or end < l:
        return 0
    if l <= start and end <= r:
        return tree[node]
    mid = (start + end) // 2
    left_sum = query(node * 2, start, mid, l, r, prefix_sum)
    right_sum = query(node * 2 + 1, mid + 1, end, l, r, prefix_sum)
    return left_sum + right_sum + prefix_sum

def update(node, start, end, idx, val, prefix_sum):
    if start == end:
        tree[node] = val * val * val
        return val * val * val
    mid = (start + end) // 2
    if idx <= mid:
        new_val = update(node * 2, start, mid, idx, val, prefix_sum)
    else:
        new_val = update(node * 2 + 1, mid + 1, end, idx, val, prefix_sum)
    tree[node] = tree[node * 2] + tree[node * 2 + 1]
    return new_val

