from collections import defaultdict

def find_max_path_length(n, edges):
    parent = [i for i in range(n)]
    rank = [0] * n

    def find(element):
        path_set = [element]
        while path_set[-1] != element:
            path_set.append(parent[path_set[-1]])
            element = parent[path_set[-1]]
        while path_set:
            element = path_set.pop()
            parent[element] = element
        return parent

    edge_count = defaultdict(int)
    for u, v in edges:
        edges[u-1][v-1] = 1
        edges[v-1][u-1] = 1
        edge_count[u-1] += 1

    def merge(u, v):
        rx, ry = find(u), find(v)
        if rx != ry:
            if rank[rx] > rank[ry]:
                rx, ry = ry, rx
            parent[rx] = ry
            if rank[rx] == rank[ry]:
                rank[ry] += 1

    for u, v, edge in edges:
        merge(u-1, v-1)
        edge_count[u-1] -= 1
        edge_count[v-1] -= 1
        if edge_count[u-1] == 0:
            merge(u, u)
            edge_count[u] = 1
        if edge_count[v-1] == 0:
            merge(v, v)
            edge_count[v] = 1

    answer = 0
    for i in range(n):
        answer += n-2*edge_count[i]

    for i in range(n):
        u = find(i)
        for j in range(n):
            u = find(u)
            if i != j and u == find(parent[j]):
                answer -= 1

    return answer - n + 2

