def max_value_in_heap(heap: list, t: int) -> int:
    # If heap has at least one element
    if heap:
        if not heap[0][0]:
            # Remove and then push the minimum value back
            x, _ = heap[0]
            heappush(heap, (x, t))
        elif heap[0][0] < t:
            # Push the minimum value back and replace it with one having same value and weigth
            x, _ = heappop(heap)
            heappush(heap, (heap[0][0], t))
        elif heap[0][0] > t:
            # Push the minimum weight value back.
            x, t_min = heap[0]
            if t_min < t:
                y, t_min_ = heappop(heap)
                heappush(heap, (x, t_min))
                heappush(heap, (y, t_min_))
