import sys

def find_tree_height(tree, index):
    # Perform DFS to find the height of the tree from the given node
    def dfs(node):
        if len(tree[node]) == 1:  # If node has only one leaf
            return 0
        vis = set()  # Set to keep track of visited nodes
        stack_ = [(node, 0)]  # Stack to help identify ancestors in the DFS
        height = 0
        while stack_:
            current_node, current_height = stack_.pop()
            vis.add(current_node)
            l = list(tree[current_node])
            for ancestor in vis:
                if ancestor in tree[current_node]:
                    l.remove(ancestor)
            if l:
                stack_.append((current_node, current_height + 1))
                height = max(height, current_height)
        return height + 1
    return dfs(index)

