import sys

def calculate_good_subsegments(p: List[int], l: int, r: int) -> int:
    n = len(p)
    dp = [0] * (n + 1)

    for i in range(n):
        if p[i] == l:
            dp[i + 1] = 1 if i > 0 else 0
        elif p[i] > l and p[i] <= r:
            for j in range(i):
                dp[p[i] + 1] += (1 if p[j] >= l else 0) * (1 if p[j] <= r else 0)

    return sum(dp)

