import heapq
from collections import defaultdict

class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.graph = defaultdict(list)

    def add_edge(self, u, v, d):
        self.graph[u].append((v, d))
        self.graph[v].append((u, d))

    def dijkstra(self, src):
        shortest_dist = {vertex: float('inf') for vertex in range(1, self.vertices + 1)}
        shortest_dist[src] = 0
        heap = [(0, src)]

        while heap:
            dist, vertex = heapq.heappop(heap)
            if shortest_dist[vertex] < dist:
                continue
            for neighbor, weight in self.graph[vertex]:
                distance = dist + weight
                if distance < shortest_dist[neighbor]:
                    shortest_dist[neighbor] = distance
                    heapq.heappush(heap, (distance, neighbor))

        return shortest_dist

def solve_queries(n, m, edges, queries):
    graph = Graph(n)
    for u, v, d in edges:
        graph.add_edge(u, v, d)

    shortest_dist = graph.dijkstra(1)
    result = []
    for u, v in queries:
        result.append(shortest_dist[u] + shortest_dist[v])

    return result

n, m = map(int, input().split())
edges = [tuple(map(int, input().split())) for _ in range(m)]
