from collections import deque

def diameterOfTree(n):
    q = deque([1])
    level = [1] * (2 * n + 1)

    while q:
        curr = q.popleft()
        degree = len(level[curr + 1:])

        for i in range(curr + 1, curr + 4 + 2):
            if i <= n:
                level[i] = max(level[i], degree + level[curr])

        for i in range(curr - 1, curr - 4 + 1, -1):
            if i >= 0:
                level[i] = max(level[i], degree + level[curr])

        q.extend([level[curr + 2], level[curr + 3]])

    return level[1] if len(level) > 2 else 2

