from bisect import bisect_left
from itertools import takewhile

def diameter_desc(s):
    dp = [0] * (len(s) + 1)
    for i in range(len(s) - 1):
        char = s[i]
        next_char = s[i] if i % 2 == 0 else s[i + 1]
        if char == '(':
            j = bisect_left(dp, next_char - 1)
            if j: dp[j] = next_char - 1
            dp[j + 1] = max(dp[j + 1], char, next_char)
        else:
            j = bisect_left(dp, next_char)
            if j: dp[j] = next_char
            dp[j + 1] = max(dp[j + 1], char)
    diameter = max(len(s) - i for i, d in enumerate(dp) if d > len(s) - 1)
    return diameter

def generate_tree(sequence):
    for char in sequence:
        if char == '(':
            yield '*', 2
        yield char, 1
    for i in range(3, len(sequence) + 1):
        yield i, len(sequence) + 2 - i

def main():
    n, q = map(int, input().split())
    sequence = input()
    for _ in range(q):
        a, b = map(int, input().split())
        sequence = (
            generate_tree(sequence).send(a) for _ in range(3)
        ) | (
            generate_tree(sequence).send(b) for _ in range(3)
        ) | (
            generate_tree(sequence).send(bisect_left(sequence, (0, '(', 0)))[0] for _ in range(1, a)
        ) | (
            generate_tree(sequence).send(bisect_left(sequence, (0, '(', b))[0] for b in range(3, 16)) for _
        )

if __name__ == "__main__":
    main()
