from sys import stdin
from math import sqrt, pow

mod = 95542721

class SegmentTree:
    def __init__(self, nums):
        self.nums = nums
        self.tree = [0] * (4 * len(nums))
        self.build(1, 0, len(nums) - 1)

    def build(self, node, start, end):
        if start == end:
            self.tree[node] = self.nums[start]
        else:
            mid = start + (end - start) // 2
            self.build(2 * node, start, mid)
            self.build(2 * node + 1, mid + 1, end)
            self.tree[node] = (self.tree[2 * node] + self.tree[2 * node + 1]) % mod

    def query(self, node, start, end, l, r, value):
        if l > end or r < start:
            return 0
        elif l <= start and end <= r:
            self.tree[node] = (self.tree[node] + pow((self.tree[2 * node] * value) % mod, 3, mod) % mod) % mod
            return self.tree[node]

        mid = start + (end - start) // 2
        max_l = self.query(2 * node, start, mid, l, r, pow(value, 3, mod))
        max_m = self.query(2 * node + 1, mid + 1, end, l, r, pow(value, 3, mod))
        return max_l + max_m % mod

def solve():
    n = int(stdin.readline())
    nums = [int(i) for i in stdin.readline().split()]
    tree = SegmentTree(nums)
    q = int(stdin.readline())
    for _ in range(q):
        type_, l, r = map(lambda x: int(x), stdin.readline().split())
        if type_ == 1:
            print(tree.query(1, 0, len(nums) - 1, l - 1, r - 1, 1), '\n')

def main():
    solve()

if __name__ == '__main__':
    main()
